import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int firstAt = 0;
        String lineInput = scanner.nextLine();
        StringBuilder output = new StringBuilder();

        for (int idx = 0; idx < lineInput.length(); idx++) {
            if (idx + 2 < lineInput.length() && lineInput.charAt(idx) == 'd' && lineInput.charAt(idx + 1) == 'o' && lineInput.charAt(idx + 2) == 't' && idx != 0 && idx + 3 <= lineInput.length()) {
                output.append('.');
                idx += 3;
                continue;
            }
            if (idx + 1 < lineInput.length() && lineInput.charAt(idx) == 'a' && lineInput.charAt(idx + 1) == 't' && idx != 0 && firstAt == 0) {
                output.append('@');
                idx += 2;
                firstAt = 1;
                continue;
            }
            output.append(lineInput.charAt(idx));
        }
        System.out.println(output.toString());
        scanner.close();
    }
}
